// Builds the page: dist/rikuy.html (the editor with its fonts and styles, one file), dist/index.html
// (the same page as a whole document), dist/git.js, dist/LICENSES.txt, and the worker's own
// scripts in dist/tex (the TeX tree's packs and wasm come from tex/build_tree.py).
// Usage: node build.mjs [--dev]   (npm run build; --dev leaves the bundle unminified, for debugging)
//   env: RIKUY_OUT     where the page goes (default dist/)
//        RIKUY_MIRROR  a full TeX Live mirror the page may read (build_tree.py mirror), e.g. "mirror/":
//                       for a self-hosted Rikuy; a page on claude.ai can reach only its own files
//        RIKUY_SHARE   the address share links open (default: the page's own, which a page in a frame lacks)
import fs from 'fs';
import path from 'path';
import { build } from 'esbuild';

const root = path.dirname(new URL(import.meta.url).pathname);
const R = (p) => path.join(root, p);
// where the built page goes (RIKUY_OUT lets tests build next to a separate set of packs)
const OUT = process.env.RIKUY_OUT || R('dist');
const O = (p) => path.join(OUT, p);
const b64 = (p) => fs.readFileSync(p).toString('base64');

// 1. sample
const sample = { 'main.tex': fs.readFileSync(R('sample/main.tex'), 'utf8'), 'refs.bib': fs.readFileSync(R('sample/refs.bib'), 'utf8') };
fs.writeFileSync(R('src/sample.js'), '// Generated by build.mjs from sample/main.tex and sample/refs.bib: edit those, not this file.\n'
  + 'export const SAMPLE = ' + JSON.stringify(sample, null, 0) + ';\n');

// 2. bundle
// RIKUY_MIRROR: where a self-hosted build keeps the full TeX Live mirror (e.g. "mirror/")
// RIKUY_SHARE: the address share links open, for a copy that cannot see its own (one inside a frame)
const out = await build({ entryPoints: [R('src/app.js')], bundle: true, format: 'iife', minify: process.argv.includes('--dev') ? false : true, write: false, target: ['chrome100', 'firefox100', 'safari15'], legalComments: 'none', charset: 'utf8', define: { __RIKUY_MIRROR__: JSON.stringify(process.env.RIKUY_MIRROR || ''), __RIKUY_SHARE__: JSON.stringify(process.env.RIKUY_SHARE || '') } });
let js = out.outputFiles[0].text.replace(/<\/script/gi, '<\\/script');

// 2b. git, loaded by the page the first time the Git panel opens; the packages it bundles keep
// their license notices in LICENSES.txt (step 8), which the banner names
const gitOut = await build({ entryPoints: [R('src/git.js')], bundle: true, format: 'esm', minify: true, write: false, metafile: true, target: ['chrome100', 'firefox100', 'safari15'], legalComments: 'none', charset: 'utf8', define: { global: 'globalThis' }, banner: { js: '/* Rikuy\'s Git panel, with isomorphic-git and the npm packages it needs; their licenses are in LICENSES.txt beside the page. */' } });
const gitJs = gitOut.outputFiles[0].text;

// 3. fonts
const F = (family, file, weight, style) => `@font-face{font-family:"${family}";src:url(data:font/woff2;base64,${b64(R('build/fonts/' + file))}) format("woff2");font-weight:${weight};font-style:${style};font-display:block}`;
const fonts = [
  F('Paper Modern Serif', 'cmu-serif-500-roman.woff2', 400, 'normal'),
  F('Paper Modern Serif', 'cmu-serif-500-italic.woff2', 400, 'italic'),
  F('Paper Modern Serif', 'cmu-serif-700-roman.woff2', 700, 'normal'),
  F('Paper Modern Serif', 'cmu-serif-700-italic.woff2', 700, 'italic'),
  F('Paper Modern Typewriter', 'cmu-typewriter-text-500-roman.woff2', 400, 'normal'),
  F('Paper Modern Sans', 'cmu-sans-serif-500-roman.woff2', 400, 'normal'),
  F('Paper Modern Sans', 'cmu-sans-serif-700-roman.woff2', 700, 'normal')
].join('\n');

// 4. KaTeX css with embedded woff2
let katexCss = fs.readFileSync(R('node_modules/katex/dist/katex.min.css'), 'utf8');
katexCss = katexCss.replace(/src:url\(fonts\/([A-Za-z0-9_-]+)\.woff2\) format\("woff2"\)(,url\([^)]*\) format\("[^"]*"\))*/g, (m, name) => `src:url(data:font/woff2;base64,${b64(R('node_modules/katex/dist/fonts/' + name + '.woff2'))}) format("woff2")`);
if (/url\(fonts\//.test(katexCss)) throw new Error('KaTeX font url left behind');

// 5. CodeMirror css
const cmCss = fs.readFileSync(R('node_modules/codemirror/lib/codemirror.css'), 'utf8');

// 6. assemble
const css = fs.readFileSync(R('src/app.css'), 'utf8');
let html = fs.readFileSync(R('src/template.html'), 'utf8');
html = html.replace('/*FONTS*/', () => fonts).replace('/*KATEX*/', () => katexCss).replace('/*CODEMIRROR*/', () => cmCss).replace('/*APP*/', () => css).replace('/*APPJS*/', () => js);
html += '\n<!-- Rikuy is free software under the GNU AGPL 3.0 or later: https://github.com/pdfrackebrandt/rikuy (SOURCES.md says where the source of every part is). Licenses of what it ships: LICENSES.txt beside this page. -->\n';
fs.mkdirSync(OUT, { recursive: true });
fs.writeFileSync(O('rikuy.html'), html);
// rikuy.html is the body the artifact host wraps in a document (test/serve.py does the same);
// index.html is that document, so any static web server can serve dist/ as it is. Without the
// doctype and charset a browser reads the page in quirks mode and as Latin-1, and the script fails.
const SKELETON = '<!doctype html><html><head><meta charset=utf8><meta name=viewport content="width=device-width,initial-scale=1,viewport-fit=cover">'
  + '<style>:root{color-scheme:light;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}'
  + 'body{margin:0;font:14px system-ui,sans-serif;background:#fafafa}img{max-width:100%}[hidden]{display:none!important}</style></head><body>';
fs.writeFileSync(O('index.html'), SKELETON + html + '</body></html>');
fs.writeFileSync(O('git.js'), gitJs);
console.log(O('rikuy.html'), (html.length / 1024).toFixed(0) + ' KB', 'js', (js.length / 1024).toFixed(0) + ' KB');

// 7. the TeX engine's own files (the packs and wasm chunks come from tex/build_tree.py)
fs.mkdirSync(O('tex'), { recursive: true });
fs.copyFileSync(R('tex/engine.js'), O('tex/engine.js'));
fs.copyFileSync(R('tex/vendor/busytex.js'), O('tex/busytex.js'));
fs.copyFileSync(R('node_modules/fflate/umd/index.js'), O('tex/fflate.js'));
fs.copyFileSync(R('tex/vendor/biber.js'), O('tex/biber.js'));
fs.copyFileSync(R('tex/shell.js'), O('tex/shell.js'));
fs.copyFileSync(R('tex/tools.js'), O('tex/tools.js'));
const escapeCtl = (t) => t.replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, (c) => '\\x' + c.charCodeAt(0).toString(16).padStart(2, '0'));
// the programs TeX's shell escape runs ship as ES modules; the worker is a classic script, so
// each becomes a script that leaves its factory on self (its wasm comes from build_tree.py)
const classic = (src, name) => {
  let t = fs.readFileSync(R(src), 'utf8');
  const n = (t.match(/import\.meta\.url/g) || []).length;
  t = t.replace(/import\.meta\.url/g, 'self.__galleyToolBase').replace(/export default Module;?/, 'self.' + name + ' = Module;');
  if (!n || !t.includes('self.' + name)) throw new Error('unexpected module shape: ' + src);
  return escapeCtl(t);
};
const gsJs = classic('node_modules/@okathira/ghostpdl-wasm/dist/gs.js', 'GalleyGs');
// tools.js resets Ghostscript's stack pointer through the exports this glue calls stackSave (Y,
// export "ba") and stackRestore (X, export "$"), as its invoke wrappers use them
if (!gsJs.includes('X=c.$;') || !gsJs.includes('Y=c.ba;') || !/var c=Y\(\);try\{T\.get\(a\)\(b\)\}catch\(d\)\{X\(c\);/.test(gsJs)) throw new Error('ghostpdl-wasm glue changed: check the stack exports in tools.js makeGs');
fs.writeFileSync(O('tex/gs.js'), gsJs);
// programs built for Rikuy (tex/build_tools.sh) are classic scripts already
for (const t of ['dvips', 'asy', 'xindy', 'gnuplot']) fs.writeFileSync(O('tex/' + t + '.js'), escapeCtl(fs.readFileSync(R('tex/vendor/' + t + '/' + t + '.js'), 'utf8')));
// Pyodide's loader is a classic script already; its runtime comes from build_tree.py
fs.writeFileSync(O('tex/pyodide.js'), escapeCtl(fs.readFileSync(R('node_modules/pyodide/pyodide.js'), 'utf8')).replace(/\n\/\/# sourceMappingURL=.*$/, '\n'));
// the artifact host refuses raw control bytes in text files; they only occur inside string
// literals here, where \xHH means the same. pdf.js itself ships beside its worker, so the page
// imports it from its own site (src/pdfview.js), never from a CDN
for (const f of ['pdf.min.mjs', 'pdf.worker.min.mjs']) fs.writeFileSync(O('tex/' + f), escapeCtl(fs.readFileSync(R('node_modules/pdfjs-dist/build/' + f), 'utf8')));
fs.copyFileSync(R('tex/tex-smoke.html'), O('tex-smoke.html'));
console.log(O('tex'), fs.readdirSync(O('tex')).length, 'files');

// 8. LICENSES.txt: NOTICE, then the license texts of what dist/ holds and the notices of the
// libraries inside its programs. The MIT, BSD and Apache licenses ask that their notices travel
// with every copy, and the minified bundles and compiled programs drop them.
// The npm packages: those git.js bundles, and those whose files the steps above copy.
const pkgOf = (f) => (f.match(/node_modules\/((?:@[^/]+\/)?[^/]+)\//) || [])[1];
const npm = new Set(Object.keys(gitOut.metafile.inputs).map(pkgOf).filter(Boolean));
for (const p of ['katex', 'codemirror', 'fflate', 'pdfjs-dist', 'pyodide']) npm.add(p);
const byText = new Map();  // packages whose license file says the same, printed once
for (const p of [...npm].sort()) {
  const dir = R('node_modules/' + p);
  const meta = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8'));
  const file = fs.readdirSync(dir).sort().find((n) => /^(licen[cs]e|copying)/i.test(n));
  const text = file ? fs.readFileSync(path.join(dir, file), 'utf8').trim() : '(The package has no license file; its package.json says ' + (meta.license || 'nothing') + ', whose text is above or at spdx.org.)';
  if (!byText.has(text)) byText.set(text, []);
  byText.get(text).push(p + ' ' + meta.version + ' (' + (meta.license || '?') + ')');
}
const rule = (title) => '\n\n' + '='.repeat(100) + '\n' + title + '\n' + '='.repeat(100) + '\n\n';
let lic = 'Rikuy and what it ships. The source of Rikuy and the address of the exact source of every\n'
  + 'part: https://github.com/pdfrackebrandt/rikuy (SOURCES.md).\n\n' + fs.readFileSync(R('NOTICE'), 'utf8').trim();
lic += rule('GNU Affero General Public License 3.0: Rikuy, BusyTeX, Ghostscript') + fs.readFileSync(R('LICENSE'), 'utf8').trim();
const texts = [['GPL-3.0', 'Asymptote as built (with GSL), GSL, Xpdf'], ['GPL-2.0', 'TeX Live\'s programs, dvips, xindy, FFTW, GMP, Xpdf, libpaper'], ['LGPL-3.0', 'GMP, Asymptote, its PRC library'],
  ['LGPL-2.1', 'kpathsea, ECL, Graphite2, TECkit, btparse'], ['MPL-2.0', 'Pyodide, Eigen'], ['Apache-2.0', 'pdf.js and npm packages below'], ['Artistic-2.0', 'biber'], ['gnuplot', 'gnuplot']];
for (const [id, who] of texts) lic += rule((id === 'gnuplot' ? 'The gnuplot license' : id) + ': ' + who) + fs.readFileSync(R('LICENSES/' + id + '.txt'), 'utf8').trim();
lic += rule('SIL Open Font License 1.1: Paper Modern, the page\'s text fonts (KaTeX\'s fonts carry the same license in their own name tables)') + fs.readFileSync(R('build/fonts/OFL.txt'), 'utf8').trim();
// the notices of the libraries compiled into the programs (MIT, BSD and the like ask for them
// with binary copies too), one file per program; each file's first line is its title
for (const f of fs.readdirSync(R('LICENSES/third-party')).filter((n) => n.endsWith('.txt')).sort()) {
  const [title, ...rest] = fs.readFileSync(R('LICENSES/third-party/' + f), 'utf8').trim().split('\n');
  lic += rule(title + ' (LICENSES/third-party/' + f + ')') + rest.join('\n').trim();
}
for (const [text, pkgs] of byText) lic += rule('npm: ' + pkgs.join(', ')) + text;
fs.writeFileSync(O('LICENSES.txt'), lic + '\n');
console.log(O('LICENSES.txt'), npm.size, 'npm packages', (lic.length / 1024).toFixed(0) + ' KB');
